    padding: 1rem;
}

/* Container */
.container {
    max-width: 600px;
    margin: 0 auto;
}

/* Typography */
h1 {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--text-primary);
}

.intro {
    color: var(--text-secondary);
    margin-bottom: 2rem;
    font-size: 0.95rem;
}

legend {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

