    const form = document.getElementById('quizForm');
    const resultDiv = document.getElementById('result');

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        handleSubmit();
    });

    function handleSubmit() {
        // Collect answers
        const answers = {
            q1: getCheckedValues('q1'),
            q2: getCheckedValues('q2'),
            q3: getCheckedValues('q3')
        };

        // Validate: at least one answer per question
        const allQuestionsAnswered = Object.values(answers).every(arr => arr.length > 0);

        if (!allQuestionsAnswered) {
            showError();
            // Focus on first empty question
            for (let q = 1; q <= 3; q++) {
                if (answers[`q${q}`].length === 0) {
                    const firstCheckbox = document.getElementById(`q${q}-a`);
                    firstCheckbox.focus();
                    break;
                }
            }
            return;
        }

        // Calculate score
        const score = calculateScore(answers);
        showSuccess(score);
    }

    function getCheckedValues(questionName) {
        const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
        return Array.from(checkboxes).map(cb => cb.value);
    }

    function calculateScore(answers) {
        let points = 0;

        // Question 1: Correct answers are C++ and Java (compiled languages)
        const q1Expected = ['cpp', 'java'];
        if (arraysMatch(answers.q1, q1Expected)) points += 1;

        // Question 2: Correct answers are JavaScript and PHP (web development)
        const q2Expected = ['javascript', 'php'];
        if (arraysMatch(answers.q2, q2Expected)) points += 1;

        // Question 3: Correct answers are Rust and C (systems programming)
        const q3Expected = ['rust', 'c'];
        if (arraysMatch(answers.q3, q3Expected)) points += 1;

        return points;
    }

    function arraysMatch(arr1, arr2) {
        if (arr1.length !== arr2.length) return false;
        const sorted1 = [...arr1].sort();
        const sorted2 = [...arr2].sort();
        return sorted1.every((val, idx) => val === sorted2[idx]);
    }

    function showSuccess(score) {
        resultDiv.className = 'result success';
        const percentage = Math.round((score / 3) * 100);
        resultDiv.innerHTML = `
            <strong>Quiz Complete!</strong><br>
            You scored ${score} out of 3 (${percentage}%)<br>
            ${getScoreFeedback(percentage)}
        `;
        resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    function getScoreFeedback(percentage) {
        if (percentage === 100) {
            return 'Perfect! You know your programming languages!';
        } else if (percentage >= 66) {
            return 'Great job! You have solid knowledge of programming languages.';
        } else if (percentage >= 33) {
            return 'Good effort! Keep learning about programming languages.';
        } else {
            return 'Try reviewing programming language characteristics.';
        }
    }

    function showError() {
        resultDiv.className = 'result hidden';
        // Could also show an inline error per question, but per requirements,
        // we focus on first empty field which is done above
    }
});
