            showError();
            // Focus on first empty question
            for (let q = 1; q <= 3; q++) {
                if (answers[`q${q}`].length === 0) {
                    const firstCheckbox = document.getElementById(`q${q}-a`);
                    firstCheckbox.focus();
                    break;
                }
            }
            return;
        }

        // Calculate score
        const score = calculateScore(answers);
        showSuccess(score);
