        resultDiv.className = 'result success';
        const percentage = Math.round((score / 3) * 100);
        resultDiv.innerHTML = `
            <strong>Quiz Complete!</strong><br>
            You scored ${score} out of 3 (${percentage}%)<br>
            ${getScoreFeedback(percentage)}
        `;
        resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    function getScoreFeedback(percentage) {
        if (percentage === 100) {
            return 'Perfect! You know your programming languages!';
        } else if (percentage >= 66) {
            return 'Great job! You have solid knowledge of programming languages.';
        } else if (percentage >= 33) {
            return 'Good effort! Keep learning about programming languages.';
        } else {
            return 'Try reviewing programming language characteristics.';
        }
    }

    function showError() {
        resultDiv.className = 'result hidden';
        // Could also show an inline error per question, but per requirements,
        // we focus on first empty field which is done above
    }
});

